// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public {
        c = new StaxLPStaking(address(this), address(this));
    }

    function testFuzz_property(address fuzzedOwner) public {
        vm.assume(fuzzedOwner != address(0));
        vm.prank(address(this));
        c.transferOwnership(fuzzedOwner);

        bool ok;
        address returnedOwner;
        try c.owner() returns (address owner_) {
            ok = true;
            returnedOwner = owner_;
        } catch {
            ok = false;
        }

        assertTrue(ok && returnedOwner == fuzzedOwner);
    }
}
